-- A public trial has no automatic deadline. Only an administrator can record
-- a customer-agreed end; existing dates/agreements are left unchanged.
begin;
insert into public.legal_document_versions(slug,version,status,sha256,document) values('terms','2026-10-03.2','published','5b6b33516c046f48a38ec84d2cc8edd22b2aa98590f22248ca9242fd1ea0ab49','{"slug":"terms","version":"2026-10-03.2","status":"published","title":"Vilkår for EmbedBot","notice":"Vilkårene er versionsregistreret. Juridisk gennemgang og bekræftelse af aftalepartens officielle oplysninger udestår.","sections":[{"title":"1. Aftalen","text":"Disse vilkår gælder for virksomhedens brug af EmbedBot, herunder dashboard, chatbot-widget, support, pilot og betalte abonnementer. Aftalen indgås med EmbedBot / Axel Bødker Frederiksen, e-mail axel@embedbot.dk , telefon +45 91 55 12 50 ."},{"title":"2. Tjenesten","text":"EmbedBot leverer en AI-baseret chatbot, som kan bruge virksomhedens egne oplysninger og websiteindhold til at besvare besøgendes spørgsmål. Funktioner, kapacitet og inkluderede AI-svar afhænger af den valgte plan. Vi kan foretage rimelige produktændringer, når tjenestens væsentlige funktion ikke forringes væsentligt."},{"title":"3. Pilot","text":"Prøveperioden tilbydes som 14 dage uden betalingskort og bliver ikke automatisk til et betalt abonnement. Adgangen afsluttes kun automatisk, hvis EmbedBot og virksomheden har aftalt en slutdato, eksempelvis i en mail. Uden aftalt slutdato fortsætter prøveadgangen, og det videre forløb aftales med virksomheden. Betaling kræver et aktivt køb. Betalte abonnementer fornyes månedligt, indtil de opsiges."},{"title":"4. Pris, betaling og fornyelse","text":"Aktuelle priser og plangrænser fremgår af prissiden . Priser er i danske kroner pr. måned og eksklusive moms, medmindre andet er angivet. Betaling håndteres af Stripe. Et betalt abonnement fornyes automatisk månedligt, indtil det opsiges. Den valgte pris, betalingsperiode og fornyelse vises før betaling. Virksomheden kan opsige i dashboardet; opsigelsen gælder ved udgangen af den allerede betalte periode. Se betalings- og refusionspolitikken ."},{"title":"5. Konto og adgang","text":"Virksomheden skal give korrekte oplysninger, beskytte loginoplysninger og straks kontakte os ved mistanke om misbrug. Virksomheden er ansvarlig for handlinger foretaget fra dens konto, medmindre de skyldes forhold, som EmbedBot er ansvarlig for."},{"title":"6. Virksomhedens indhold og instruktioner","text":"Virksomheden beholder sine rettigheder til indhold, som den leverer. Virksomheden giver EmbedBot en begrænset ret til at behandle indholdet for at levere, sikre og supportere tjenesten. Virksomheden er ansvarlig for, at den har ret til at bruge og dele indholdet, og for at produkt-, pris-, leverings-, retur-, garanti- og kontaktoplysninger er korrekte. Virksomheden skal gennemgå væsentlige chatbot-svar og må ikke instruere chatbotten i at vildlede kunder eller overtræde lovgivning."},{"title":"7. Personoplysninger","text":"Når EmbedBot behandler virksomhedens besøgendes oplysninger efter virksomhedens instruktioner, er virksomheden normalt dataansvarlig og EmbedBot databehandler. Virksomheden skal give de nødvendige oplysninger til sine besøgende, vælge et lovligt behandlingsgrundlag og undgå at indsamle flere oplysninger end nødvendigt. En databehandleraftale skal være indgået, før EmbedBot bruges til at behandle besøgendes personoplysninger på virksomhedens vegne. Se privatlivspolitikken og cookiepolitikken ."},{"title":"8. Børn og følsomme oplysninger","text":"Tjenesten er ikke målrettet børn. Virksomheden må ikke målrette chatbotten mod børn eller indsamle børns oplysninger på grundlag af samtykke uden selv at sikre et gyldigt alders- og forældresamtykkeforløb. Chatbotten bør ikke bruges til CPR-numre, helbredsoplysninger, betalingskortoplysninger eller andre følsomme oplysninger, medmindre det er særskilt aftalt og lovligt."},{"title":"9. Acceptabel brug","text":"EmbedBot må ikke bruges til ulovligt indhold, spam, phishing, chikane, malware, krænkelse af tredjemands rettigheder, omgåelse af sikkerhed eller belastning af tjenesten ud over normal brug. Sikkerhedsforanstaltninger må ikke testes uden skriftlig tilladelse."},{"title":"10. AI-begrænsninger","text":"AI-genererede svar kan være ufuldstændige eller forkerte. EmbedBot bruger tekniske og instruktionelle sikkerhedsforanstaltninger, men kan ikke garantere, at alle fejl, manipulationer eller prompt-injection-forsøg bliver opdaget. Chatbotten må ikke være eneste grundlag for juridisk, medicinsk, finansiel eller anden højrisikorådgivning."},{"title":"11. Tredjeparter","text":"Tjenesten anvender blandt andet OpenAI, Supabase, Stripe, Resend, Vercel og Plausible. Driftsforstyrrelser eller ændringer hos disse leverandører kan påvirke tjenesten. Vi vælger og administrerer leverandører med rimelig omhu, men kan ikke kontrollere deres tjenester fuldt ud."},{"title":"12. Tilgængelighed, support og sikkerhed","text":"Vi tilstræber stabil drift og rimelig support, men lover ikke uafbrudt eller fejlfri adgang. Planlagt vedligeholdelse, sikkerhedshændelser eller forhold uden for vores kontrol kan give afbrydelser. Vi anvender rimelige tekniske og organisatoriske sikkerhedsforanstaltninger."},{"title":"13. Suspension og ophør","text":"Vi kan suspendere adgang ved manglende betaling, væsentlig misligholdelse, sikkerhedsrisiko eller ulovlig brug. Hvor det er rimeligt, giver vi mulighed for at rette forholdet først. Ved ophør bør virksomheden eksportere nødvendige data. Sletning og opbevaring følger privatlivspolitikken og gældende lov."},{"title":"14. Ansvar","text":"Parterne er ansvarlige efter dansk rets almindelige regler med de begrænsninger, der lovligt kan aftales mellem erhvervsdrivende. EmbedBot er ikke ansvarlig for indirekte tab, driftstab, tabt avance eller tab, der skyldes virksomhedens urigtige indhold eller brug af AI-svar uden relevant kontrol. EmbedBots samlede ansvar er, i det omfang loven tillader det, begrænset til det beløb, virksomheden har betalt for tjenesten i de seneste 12 måneder. Begrænsningen gælder ikke ved forsæt, grov uagtsomhed eller ansvar, som ikke lovligt kan begrænses."},{"title":"15. Ændringer","text":"Væsentlige ændringer til priser eller vilkår varsles normalt mindst 30 dage før ikrafttræden. Hvis en ændring har væsentlig negativ betydning, kan virksomheden opsige abonnementet inden ændringen træder i kraft."},{"title":"16. Lovvalg og kontakt","text":"Aftalen er underlagt dansk ret. Tvister søges først løst i dialog og kan derefter indbringes for de danske domstole efter de almindelige værnetingsregler. Spørgsmål kan sendes til axel@embedbot.dk eller via support ."}],"suppliers":[],"sha256":"5b6b33516c046f48a38ec84d2cc8edd22b2aa98590f22248ca9242fd1ea0ab49"}'::jsonb);

create or replace function public.start_embedbot_trial(p_business_id uuid,p_actor uuid,p_terms_version text) returns timestamptz
language plpgsql security invoker set search_path='' as $$ declare b public.businesses%rowtype; begin
 perform public.compliance_assert_owner(p_business_id,p_actor);
 select * into b from public.businesses where id=p_business_id for update;
 if not exists(select 1 from public.legal_acceptances where business_id=p_business_id and slug='terms' and version=p_terms_version) then raise exception 'terms_required'; end if;
 if b.current_period_end is not null or b.activated_at is not null or b.stripe_subscription_id is not null then
  if b.stripe_subscription_id is null and b.payment_status='unpaid' and b.subscription_status='trialing' and b.activated and (b.current_period_end is null or b.current_period_end>now()) then return b.current_period_end; end if;
  raise exception 'trial_already_used';
 end if;
 update public.businesses set activated=true,activated_at=now(),subscription_status='trialing',payment_status='unpaid',current_period_end=null,plan='starter',subscription_updated_at=now() where id=p_business_id;
 insert into public.compliance_audit_events(actor_user_id,business_id,action) values(p_actor,p_business_id,'trial.start');
 return null;
end $$;
revoke all on function public.start_embedbot_trial(uuid,uuid,text) from public,anon,authenticated;
grant execute on function public.start_embedbot_trial(uuid,uuid,text) to service_role;
commit;
